import fs from 'node:fs';
import path from 'node:path';

const dir = process.env.DEVNS_BROWSER_SMOKE_ARTIFACT_ABS_DIR;
if (!dir) throw new Error('DEVNS_BROWSER_SMOKE_ARTIFACT_ABS_DIR is required');
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, 'visible-text.txt'), 'DEVNS T3 Dashboard\nArtifacts: screenshot trace console network\nSample URL http://127.0.0.1:5173/\nPolicy findings none\n');
fs.writeFileSync(path.join(dir, 'dom-snapshot.html'), '<main><h1>DEVNS T3 Dashboard</h1><p>Browser semantic snapshot ready.</p></main>\n');
fs.writeFileSync(path.join(dir, 'accessibility.json'), JSON.stringify({ role: 'main', name: 'DEVNS T3 Dashboard', children: [{ role: 'heading', name: 'DEVNS T3 Dashboard' }] }, null, 2) + '\n');
fs.writeFileSync(path.join(dir, 'console.ndjson'), JSON.stringify({ type: 'log', text: 'seed ok' }) + '\n');
fs.writeFileSync(path.join(dir, 'network.ndjson'), JSON.stringify({ url: 'http://127.0.0.1:5173/', status: 200, failed: false }) + '\n');
